      if !business_profile_record_id.nil? && business_profile_record_id.to_s.length < 36
        fail ArgumentError, 'invalid value for "business_profile_record_id", the character length must be great than or equal to 36.'
      end

      @business_profile_record_id = business_profile_record_id
    end

    # Checks equality by comparing each attribute.
    # @param [Object] Object to be compared
    def ==(o)
      return true if self.equal?(o)
      self.class == o.class &&
          id == o.id &&
          timestamp == o.timestamp &&
          is_extended_warranty == o.is_extended_warranty &&
          code == o.code &&
          title == o.title &&
          description == o.description &&
          is_free == o.is_free &&
          reduce == o.reduce &&
          is_enabled == o.is_enabled &&
          is_default == o.is_default &&
          allow_international == o.allow_international &&
          hours == o.hours &&
          days == o.days &&
          weeks == o.weeks &&
          months == o.months &&
          years == o.years &&
          value == o.value &&
          percentage == o.percentage &&
          currency_id == o.currency_id &&
          country_id == o.country_id &&
          country_state_id == o.country_state_id &&
          custom_state == o.custom_state &&
          custom_city == o.custom_city &&
          city_id == o.city_id &&
          business_id == o.business_id &&
          business_profile_record_id == o.business_profile_record_id
    end

    # @see the `==` method
    # @param [Object] Object to be compared
    def eql?(o)
